package com.alpharip.staffmod.AuditFindingsBoard;
import java.util.*;
public final class AuditFinding {
 private final String id;private final long createdAt;private String title,description,owner;private AuditFindingCategory category;private AuditFindingSeverity severity;private AuditFindingStatus status;private long updatedAt,dueAt;
 private final List<AuditFindingAssignment> assignments=new ArrayList<AuditFindingAssignment>();private final List<AuditFindingNote> notes=new ArrayList<AuditFindingNote>();private final List<AuditFindingAction> actions=new ArrayList<AuditFindingAction>();private final List<AuditFindingHistoryEntry> history=new ArrayList<AuditFindingHistoryEntry>();private final List<AuditFindingEvidenceReference> evidence=new ArrayList<AuditFindingEvidenceReference>();private AuditFindingResolution resolution;
 public AuditFinding(String id,String t,String d,AuditFindingCategory c,AuditFindingSeverity s,String o,long due,long now){if(id==null||id.trim().isEmpty())throw new IllegalArgumentException("Finding ID required");this.id=id;createdAt=Math.max(0L,now);status=AuditFindingStatus.OPEN;revise(t,d,c,s,o,due,now);record("","CREATED","Finding created",now);}
 public String getId(){return id;}public String getTitle(){return title;}public String getDescription(){return description;}public String getOwner(){return owner;}public AuditFindingCategory getCategory(){return category;}public AuditFindingSeverity getSeverity(){return severity;}public AuditFindingStatus getStatus(){return status;}public long getCreatedAt(){return createdAt;}public long getUpdatedAt(){return updatedAt;}public long getDueAt(){return dueAt;}public AuditFindingResolution getResolution(){return resolution;}
 public List<AuditFindingAssignment> getAssignments(){return Collections.unmodifiableList(new ArrayList<AuditFindingAssignment>(assignments));}public List<AuditFindingNote> getNotes(){return Collections.unmodifiableList(new ArrayList<AuditFindingNote>(notes));}public List<AuditFindingAction> getActions(){return Collections.unmodifiableList(new ArrayList<AuditFindingAction>(actions));}public List<AuditFindingHistoryEntry> getHistory(){return Collections.unmodifiableList(new ArrayList<AuditFindingHistoryEntry>(history));}public List<AuditFindingEvidenceReference> getEvidence(){return Collections.unmodifiableList(new ArrayList<AuditFindingEvidenceReference>(evidence));}
 public void revise(String t,String d,AuditFindingCategory c,AuditFindingSeverity s,String o,long due,long now){AuditFindingsValidator.validate(t,d,c,s);title=t.trim();description=d.trim();category=c;severity=s;owner=o==null?"":o.trim();dueAt=Math.max(0L,due);touch(now);}
 public void setStatus(AuditFindingStatus next,String actor,long now){if(next==null)throw new IllegalArgumentException("Status required");AuditFindingStatus old=status;status=next;touch(now);record(actor,"STATUS_CHANGED",old+" -> "+next,now);}
 public void assign(String who,String actor,long now){AuditFindingAssignment a=new AuditFindingAssignment(who,actor,now);assignments.add(a);owner=a.getAssignee();touch(now);record(actor,"ASSIGNED","Assigned to "+owner,now);}
 public void addNote(String author,String text,long now){notes.add(new AuditFindingNote(author,text,now));touch(now);record(author,"NOTE_ADDED","Internal note added",now);}
 public void addAction(String text,String assignee,long now){actions.add(new AuditFindingAction(UUID.randomUUID().toString(),text,assignee,now));touch(now);record(assignee,"ACTION_ADDED",text,now);}
 public void completeAction(String actionId,boolean complete,long now){for(AuditFindingAction a:actions)if(a.getId().equals(actionId)){a.setCompleted(complete,now);touch(now);record("","ACTION_UPDATED",a.getText(),now);return;}throw new IllegalArgumentException("Action not found");}
 public void addEvidence(String label,String ref,String actor,long now){evidence.add(new AuditFindingEvidenceReference(label,ref,actor,now));touch(now);record(actor,"EVIDENCE_LINKED",label,now);}
 public void resolve(String outcome,String rationale,String actor,long now){resolution=new AuditFindingResolution(outcome,rationale,actor,now);status=AuditFindingStatus.RESOLVED;touch(now);record(actor,"RESOLVED",outcome,now);}
 private void record(String actor,String event,String details,long now){history.add(new AuditFindingHistoryEntry(actor,event,details,now));}private void touch(long now){updatedAt=Math.max(0L,now);}
}
